from __future__ import annotations

from collections.abc import Callable
from datetime import UTC, datetime
from uuid import UUID, uuid4

import pytest
from sqlalchemy import create_engine, text

from hyc_api.contracts import BoundingBox, ExtractionCandidate, ExtractionValue, SourceReference

pytestmark = pytest.mark.postgres


class GeneratedLocalProvider:
    """Injection-only provider for generated bytes; it never reads source evidence."""

    def extract(
        self,
        document_id: str,
        source_reference: str,
        *,
        document_bytes: bytes | None = None,
    ) -> ExtractionCandidate:
        assert document_bytes is not None and document_bytes.startswith(b"%PDF-")
        reference = SourceReference(
            document_id=UUID(document_id),
            source_reference=source_reference,
            page_number=1,
            bbox=BoundingBox(left=0.1, top=0.1, right=0.9, bottom=0.2),
        )
        return ExtractionCandidate(
            schema_version="1.0",
            candidate_id=uuid4(),
            created_at=datetime.now(UTC),
            document=reference,
            provider_name="local-paddleocr",
            values=[
                ExtractionValue(
                    item_key="OCR_TEXT_0001",
                    raw_text="96.50",
                    normalized_value=None,
                    provenance=reference,
                    confidence=0.9,
                    review_required=True,
                    reading_order=1,
                    recipe_id="original",
                    variant_id="original-r0",
                    rotation_degrees=0,
                    deskew_millidegrees=0,
                    deskew_status="NOT_NEEDED",
                    perspective_corrected=False,
                    reason_codes=["HUMAN_REVIEW_REQUIRED"],
                ),
                ExtractionValue(
                    item_key="OCR_TEXT_0002",
                    raw_text="generated note",
                    normalized_value=None,
                    provenance=reference,
                    confidence=0.7,
                    review_required=True,
                    reading_order=2,
                    recipe_id="original",
                    variant_id="original-r0",
                    rotation_degrees=0,
                    deskew_millidegrees=0,
                    deskew_status="NOT_NEEDED",
                    perspective_corrected=False,
                    reason_codes=["LOW_CONFIDENCE"],
                ),
            ],
            review_required=True,
        )


class FailingLocalProvider:
    def extract(
        self,
        document_id: str,
        source_reference: str,
        *,
        document_bytes: bytes | None = None,
    ) -> ExtractionCandidate:
        del document_id, source_reference, document_bytes
        raise RuntimeError("generated provider failure")


def _local_run(p3, provider=None) -> tuple[dict[str, object], dict[str, object]]:
    marker = uuid4().hex
    intake = p3.intake(suffix=marker)
    original_enabled = p3.client.app.state.settings.local_ocr_enabled
    original_provider = p3.client.app.state.local_ocr_provider
    p3.client.app.state.settings.local_ocr_enabled = True
    p3.client.app.state.local_ocr_provider = provider or GeneratedLocalProvider()
    try:
        document = p3.client.post(
            "/api/v1/documents",
            content=f"%PDF-generated-{marker}".encode(),
            headers=p3.inspector
            | {"X-Filename": "generated.pdf", "Content-Type": "application/pdf"},
        )
        assert document.status_code == 201, document.text
        extraction = p3.client.post(
            f"/api/v1/documents/{document.json()['document_id']}/extractions",
            headers=p3.inspector,
        )
        return intake | document.json(), extraction.json() if extraction.status_code == 201 else {
            "status_code": extraction.status_code,
            "body": extraction.json(),
        }
    finally:
        p3.client.app.state.settings.local_ocr_enabled = original_enabled
        p3.client.app.state.local_ocr_provider = original_provider


def _review_fields(run: dict[str, object]) -> list[dict[str, object]]:
    fields = run["fields"]
    assert isinstance(fields, list)
    return [
        {
            "field_id": field["field_id"],
            "field_key": field["source_field_key"],
            "manual_text": None,
            "final_text": "96.50" if index == 0 else "generated note",
            "source": "OCR",
            "reason": "generated-only human review",
            "logic_conflict": False,
            "mapping_disposition": "MAP" if index == 0 else "UNMAPPED",
            "mapped_field_key": "CACL2_PURITY" if index == 0 else None,
        }
        for index, field in enumerate(fields)
    ]


def _confirm(p3, context: dict[str, object], run: dict[str, object], fields=None):
    return p3.client.put(
        f"/api/v1/documents/{context['document_id']}/reviews/{run['run_id']}",
        json={
            "allocation_id": context["allocation_id"],
            "spec_version_id": p3.context["spec_version_id"],
            "fields": fields if fields is not None else _review_fields(run),
        },
        headers=p3.inspector | {"If-Match": str(run["version"])},
    )


def test_pdf_without_local_flag_fails_closed_without_fixture_values(p3) -> None:
    document = p3.client.post(
        "/api/v1/documents",
        content=f"%PDF-generated-disabled-{uuid4().hex}".encode(),
        headers=p3.inspector | {"X-Filename": "generated.pdf", "Content-Type": "application/pdf"},
    )
    response = p3.client.post(
        f"/api/v1/documents/{document.json()['document_id']}/extractions",
        headers=p3.inspector,
    )
    assert response.status_code == 422
    assert response.json()["message"] == "LOCAL_OCR_DISABLED"
    assert "P3-SYNTH" not in response.text


def test_verified_pdf_bytes_override_octet_stream_and_deduplicated_headers(p3) -> None:
    payload = f"%PDF-generated-octet-{uuid4().hex}".encode()
    first = p3.client.post(
        "/api/v1/documents",
        content=payload,
        headers=p3.inspector
        | {"X-Filename": "mismatch.bin", "Content-Type": "application/octet-stream"},
    )
    assert first.status_code == 201, first.text
    disabled = p3.client.post(
        f"/api/v1/documents/{first.json()['document_id']}/extractions", headers=p3.inspector
    )
    assert disabled.status_code == 422
    assert disabled.json()["message"] == "LOCAL_OCR_DISABLED"
    assert "P3-SYNTH" not in disabled.text

    duplicate = p3.client.post(
        "/api/v1/documents",
        content=payload,
        headers=p3.inspector | {"X-Filename": "mismatch.txt", "Content-Type": "text/plain"},
    )
    assert duplicate.status_code == 200, duplicate.text
    assert duplicate.json()["document_id"] == first.json()["document_id"]
    engine = create_engine(p3.database_url)
    with engine.connect() as connection:
        row = connection.execute(
            text("SELECT document_type, media_type FROM documents WHERE id = :document_id"),
            {"document_id": first.json()["document_id"]},
        ).one()
    engine.dispose()
    assert row == ("COA_PDF", "application/pdf")

    original_enabled = p3.client.app.state.settings.local_ocr_enabled
    original_provider = p3.client.app.state.local_ocr_provider
    p3.client.app.state.settings.local_ocr_enabled = True
    p3.client.app.state.local_ocr_provider = GeneratedLocalProvider()
    try:
        enabled = p3.client.post(
            f"/api/v1/documents/{first.json()['document_id']}/extractions", headers=p3.inspector
        )
    finally:
        p3.client.app.state.settings.local_ocr_enabled = original_enabled
        p3.client.app.state.local_ocr_provider = original_provider
    assert enabled.status_code == 201, enabled.text
    assert enabled.json()["provider_name"] == "local-paddleocr"


def test_legacy_document_metadata_is_not_updated_and_verified_bytes_route_extraction(p3) -> None:
    payload = f"%PDF-legacy-metadata-{uuid4().hex}".encode()
    document = p3.client.post(
        "/api/v1/documents",
        content=payload,
        headers=p3.inspector | {"X-Filename": "legacy.pdf"},
    )
    assert document.status_code == 201, document.text
    engine = create_engine(p3.database_url)
    try:
        with engine.begin() as connection:
            connection.execute(text("SET LOCAL session_replication_role = replica"))
            connection.execute(
                text(
                    "UPDATE documents SET document_type = 'SYNTHETIC_COA', "
                    "media_type = 'application/octet-stream' WHERE id = :document_id"
                ),
                {"document_id": document.json()["document_id"]},
            )
        duplicate = p3.client.post(
            "/api/v1/documents",
            content=payload,
            headers=p3.inspector | {"X-Filename": "legacy-duplicate.bin"},
        )
        assert duplicate.status_code == 200, duplicate.text
        with engine.connect() as connection:
            assert connection.execute(
                text("SELECT document_type, media_type FROM documents WHERE id = :document_id"),
                {"document_id": document.json()["document_id"]},
            ).one() == ("SYNTHETIC_COA", "application/octet-stream")
        original_enabled = p3.client.app.state.settings.local_ocr_enabled
        original_provider = p3.client.app.state.local_ocr_provider
        p3.client.app.state.settings.local_ocr_enabled = True
        p3.client.app.state.local_ocr_provider = GeneratedLocalProvider()
        try:
            extraction = p3.client.post(
                f"/api/v1/documents/{document.json()['document_id']}/extractions",
                headers=p3.inspector,
            )
        finally:
            p3.client.app.state.settings.local_ocr_enabled = original_enabled
            p3.client.app.state.local_ocr_provider = original_provider
        assert extraction.status_code == 201, extraction.text
        assert extraction.json()["provider_name"] == "local-paddleocr"
    finally:
        engine.dispose()


