def test_provider_failure_leaves_no_partial_run_or_field(p3) -> None:
    engine = create_engine(p3.database_url)
    with engine.connect() as connection:
        before = connection.execute(text("SELECT count(*) FROM extraction_runs")).scalar_one()
    _context, failure = _local_run(p3, FailingLocalProvider())
    assert failure["status_code"] == 500
    with engine.connect() as connection:
        assert (
            connection.execute(text("SELECT count(*) FROM extraction_runs")).scalar_one() == before
        )
    engine.dispose()


def test_local_persistence_resume_and_explicit_review_create_only_mapped_supplier_result(
    p3,
) -> None:
    context, run = _local_run(p3)
    assert run["provider_name"] == "local-paddleocr"
    assert run["status"] == "REVIEW_REQUIRED"
    assert all(field["status"] == "REVIEW_REQUIRED" for field in run["fields"])
    assert "storage" not in str(run["fields"]).lower()

    resumed = p3.client.get(
        f"/api/v1/documents/{context['document_id']}/extractions/{run['run_id']}",
        headers=p3.inspector,
    )
    assert resumed.status_code == 200
    assert resumed.json() == run
    assert (
        p3.client.get(
            f"/api/v1/documents/{uuid4()}/extractions/{run['run_id']}",
            headers=p3.inspector,
        ).status_code
        == 404
    )

    review = _confirm(p3, context, run)
    assert review.status_code == 200, review.text
    reviewed = review.json()
    assert {field["mapping_disposition"] for field in reviewed["fields"]} == {"MAP", "UNMAPPED"}
    assert (
        next(field for field in reviewed["fields"] if field["mapping_disposition"] == "MAP")[
            "field_key"
        ]
        == "CACL2_PURITY"
    )

    created = p3.client.post(
        "/api/v1/inspections",
        json={"allocation_id": context["allocation_id"], "extraction_run_id": run["run_id"]},
        headers=p3.inspector | {"Idempotency-Key": f"local-ocr-{uuid4().hex}"},
    )
    assert created.status_code == 201, created.text
    engine = create_engine(p3.database_url)
    with engine.connect() as connection:
        rows = connection.execute(
            text(
                "SELECT sti.code, sr.normalized_value FROM supplier_results sr "
                "JOIN standard_test_items sti ON sti.id = sr.standard_test_item_id "
                "WHERE sr.inspection_case_id = :case"
            ),
            {"case": created.json()["inspection_id"]},
        ).all()
    engine.dispose()
    assert [(code, str(value)) for code, value in rows] == [("CACL2_PURITY", "96.500000000000")]


@pytest.mark.parametrize(
    "invalid",
    ["", " 1", "1 ", "1 kg", "1,0", "+1", "1e2", "NaN", "Infinity", 1, 1.0],
    ids=[
        "empty",
        "leading-space",
        "trailing-space",
        "unit",
        "comma",
        "plus",
        "exponent",
        "nan",
        "infinity",
        "integer",
        "float",
    ],
)
def test_noncanonical_mapped_values_reject_before_mutation(p3, invalid: object) -> None:
    context, run = _local_run(p3)
    fields = _review_fields(run)
    fields[0]["final_text"] = invalid
    rejected = _confirm(p3, context, run, fields)
    assert rejected.status_code == 422, rejected.text
    assert _confirm(p3, context, run).status_code == 200


@pytest.mark.parametrize(
    "invalid",
    ["1000000000000", "0.1234567890123"],
    ids=["thirteen-integer-digits", "thirteen-fractional-digits"],
)
def test_numeric_storage_bounds_reject_at_confirm_without_partial_mutation(
    p3, invalid: str
) -> None:
    context, run = _local_run(p3)
    fields = _review_fields(run)
    fields[0]["final_text"] = invalid
    rejected = _confirm(p3, context, run, fields)
