@pytest.mark.parametrize(
    "invalid",
    ["96.50 ", "1000000000000", "0.1234567890123"],
    ids=["noncanonical", "thirteen-integer-digits", "thirteen-fractional-digits"],
)
def test_failed_inspection_validation_releases_idempotency_reservation_after_repair(
    p3, invalid: str
) -> None:
    context, run = _local_run(p3)
    assert _confirm(p3, context, run).status_code == 200
    engine = create_engine(p3.database_url)
    try:
        with engine.begin() as connection:
            connection.execute(text("SET LOCAL session_replication_role = replica"))
            connection.execute(
                text(
                    "UPDATE extraction_field_reviews SET final_text = :invalid "
                    "WHERE extraction_run_id = :run AND field_key = 'CACL2_PURITY'"
                ),
                {"invalid": invalid, "run": run["run_id"]},
            )
        key = f"retry-after-repair-{uuid4().hex}"
        payload = {"allocation_id": context["allocation_id"], "extraction_run_id": run["run_id"]}
        failed = p3.client.post(
            "/api/v1/inspections",
            json=payload,
            headers=p3.inspector | {"Idempotency-Key": key},
        )
        assert failed.status_code == 422, failed.text
        with engine.connect() as connection:
            assert (
                connection.execute(
                    text("SELECT count(*) FROM idempotency_keys WHERE key = :key"), {"key": key}
                ).scalar_one()
                == 0
            )
        with engine.begin() as connection:
            connection.execute(text("SET LOCAL session_replication_role = replica"))
            connection.execute(
                text(
                    "UPDATE extraction_field_reviews SET final_text = '96.50' "
                    "WHERE extraction_run_id = :run AND field_key = 'CACL2_PURITY'"
                ),
                {"run": run["run_id"]},
            )
        retried = p3.client.post(
            "/api/v1/inspections",
            json=payload,
            headers=p3.inspector | {"Idempotency-Key": key},
        )
        assert retried.status_code == 201, retried.text
    finally:
        engine.dispose()


def test_completed_idempotency_conflict_wins_before_invalid_resource_validation(p3) -> None:
    context = p3.reviewed_extraction()
    key = f"completed-key-priority-{uuid4().hex}"
    payload = {"allocation_id": context["allocation_id"], "extraction_run_id": context["run_id"]}
    first = p3.client.post(
        "/api/v1/inspections", json=payload, headers=p3.inspector | {"Idempotency-Key": key}
    )
    assert first.status_code == 201, first.text
    conflict = p3.client.post(
        "/api/v1/inspections",
        json={"allocation_id": str(uuid4()), "extraction_run_id": str(uuid4())},
        headers=p3.inspector | {"Idempotency-Key": key},
    )
    assert conflict.status_code == 409
    assert conflict.json()["message"] == "Idempotency key request conflict"


