@pytest.mark.parametrize("tamper", ["decimal", "mapping", "spec"])
def test_create_inspection_independently_rejects_tampered_confirmed_records(
    p3, tamper: str
) -> None:
    context, run = _local_run(p3)
    assert _confirm(p3, context, run).status_code == 200
    engine = create_engine(p3.database_url)
    with engine.begin() as connection:
        before = connection.execute(text("SELECT count(*) FROM inspection_cases")).scalar_one()
        connection.execute(text("SET LOCAL session_replication_role = replica"))
        if tamper == "decimal":
            connection.execute(
                text(
                    "UPDATE extraction_field_reviews SET final_text = '96.50 ' "
                    "WHERE extraction_run_id = :run AND field_key = 'CACL2_PURITY'"
                ),
                {"run": run["run_id"]},
            )
        elif tamper == "mapping":
            connection.execute(
                text(
                    "UPDATE extraction_field_reviews SET field_key = 'NOT_IN_CURRENT_SPEC' "
                    "WHERE extraction_run_id = :run AND field_key = 'CACL2_PURITY'"
                ),
                {"run": run["run_id"]},
            )
        else:
            connection.execute(
                text(
                    "UPDATE extraction_runs SET candidate_payload = "
                    "jsonb_set(candidate_payload::jsonb, '{review,spec_version_id}', "
                    "to_jsonb(CAST(:spec AS text)))::json WHERE id = :run"
                ),
                {"run": run["run_id"], "spec": str(uuid4())},
            )
    response = p3.client.post(
        "/api/v1/inspections",
        json={"allocation_id": context["allocation_id"], "extraction_run_id": run["run_id"]},
        headers=p3.inspector | {"Idempotency-Key": f"tamper-{uuid4().hex}"},
    )
    assert response.status_code == 422, response.text
    with engine.connect() as connection:
        assert (
            connection.execute(text("SELECT count(*) FROM inspection_cases")).scalar_one() == before
        )
    engine.dispose()
